VALUES ('recVYd34ecqeWCciU', 'extraescolar-atletisme-sub-10-9-10-anys-geieg-palau-sacosta-girona-montilivi-palau-girona', 'Atletisme Sub-10', 'GEiEG - Palau Sacosta', 'recgetecLsdwmaX6k', 'Girona - Montilivi-Palau', 'Esports', '"Esports"', '9-10 anys', '41', FALSE, FALSE, FALSE, '17:45 a 19:15 h', 'Dilluns i dimecres', 'Descobreix l’atletisme com mai ho has fet! Uneix-te a una secció que combina gairebé 100 anys d’història amb la il·lusió i l’energia del futur. Amb el GEiEG, l’esport es transforma en una experiència emocionant per a totes les edats i nivells.', '', '', 'Per fer aquesta activitat cal ser soci del GEiEG (és un quota addicional al preu de l’activitat)', '', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/qifjfKF0CjpKvVjLu0C7bA/nqCXgiTep5r-aun55OujxBL2PrXzVVrqhqZ2pmOSPdVmyQ7qcYMcejed4vEP8h0YBUkJwq1pqBSl9F33rNF72eJ-SQpnIPgzwmDfEn8D0widVhieO9KaWQRV_Y8tf0ucEL_gFAkqg6tK4c6DXoogmnIczSf4NfXNCpX4s3F9zNHMwU-XsGqv0aFR0ziTZU8e/vxQD_rGFVjfp4YGd5kmWD51ToM7RuG8No1vzcdHPmPA', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/2CTBJ31PSrlN7nXf72xRWw/hkp9TfkeueicWVwhAJuW_33xLL8E5UG1LzpfH_8BEffqtFOmGDJB4VescjHYpYOiWSjycahUUVAt0sJSN_lDICh0hlF2oxI7E9I82oVV1tFrbXz9694VjxA59Rlu4sCKLoprn_YQrnfXfXoDD58IkQ/jvd6S-GZ4wmSNUXS7e6AdG1W-3QLvHBJtGREzTwpDhg', '{}', 'Atletisme', 'Extraescolar', '', '', '', '', 'girona')
