VALUES ('recVqwnaq1K1RxcxG', 'extraescolar-guitarra-baix-a-partir-de-6-anys-escola-de-musica-sant-gregori-sant-gregori-girona', 'Guitarra / Baix', 'Escola de Música Sant Gregori', 'rec8bSYPwdb4jZCLe', 'Sant Gregori', 'Música', '"Música"', 'A partir de 6 anys', '30''→60€ | 40''→80€ | 50''→100€ | 60''→120€', FALSE, TRUE, FALSE, '', 'Dimarts i dimecres', 'Pedagogia activa basada en la participació activa, l''expressió vocal, el moviment corporal i la improvisació, amb l''objectiu de desenvolupar l''oïda, la veu, el sentit rítmic... fent que tots els alumnes gaudeixin i creixin gràcies a la música', '', '', '', '', '', 'Marcel Torres', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/288WF1TWZHjhQh1U43Sbhg/QDsojtJBoROsMhtdgwgOnr9X1l1QbUfK7865TjzNdI-zmqhvmJdbXcEJtsem4HdVuxmYJdFod_3JKKav6845b6g8dLJPcGQ7ZgaduVRKZPG3oar1YnyKlfay-JDL3oxaMlNBrlznUv3iKoT_qQApDOjnzbPspVFoJR9Xb2dO4IEUCc2hGTmWRs6Z8Qe3ntPV/30Wq8yeN2mPK6QKod8Encjmm1_3iOQeC5fF0FqookZE', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/7UR3EuH3iegDnCvvtShNkw/EL4_10TUdk15pQmJBGyVR7yo8isF3wY4aah5RQ41BvALKSYuMcwg-eb2UicAHV9YThvbSAbpe3iUnM3aHT-YLq8y6lAKE7GYb8jWcSqTDMQ8YxTQ8B4b-rVP4B_FpwKuwRihmOoTPYgyk2wXSGiy7Q/JpMsJOfV2IoK-mjvii5oqYah92AjkHVgDlnG-zpEznw', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
