VALUES ('recWFcVdV7F9jOhxQ', 'extraescolar-innovat-3-robotica-avancada-12-17-innova-t-educacio-girona-eixample-girona', 'Innovat 3 - Robotica Avançada', 'Innova''t Educació', 'recPLNJCBuYgE3BwV', 'Girona - Eixample', 'Programació i robòtica', '"Programació i robòtica"', '12-17', '', FALSE, FALSE, FALSE, '17:30-19:00', 'Dimarts i/o Dimecres', 'Robotica avançada per a alumnes de secundaria. Bases de diversos sistemes robotics i programacio. Treball amb robots VEX Robotics o Lego Mindstorms. Desenvolupament de projectes tecnologics personalitzats. Participacio opcional en competicions de robotica al llarg del curs. Cultura maker amb impressores 3D i softwares de modelat 3D com Sketchup. Desenvolupament de dissenys i prototips propis.', '90min', 'Grups reduits', '', 'Setembre', 'Catala', 'Grups reduits', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
