VALUES ('recXENCMZzHDJ9K7X', 'taller-cercle-de-les-emocions-de-5-a-18-anys-associacio-reach-girona-eixample-girona', 'Cercle de les Emocions', 'Associació Reach', 'recGAl2tXVi7wZkwb', 'Girona - Eixample', 'Salut i benestar', '"Salut i benestar"', 'De 5 a 18 anys', '50 €', FALSE, TRUE, FALSE, 'Tarda', 'Dilluns i divendres ', 'Activitat orientada a potenciar les habilitats acadèmiques, cognitives i comunicatives dels infants i adolescents. Les sessions s''adapten a les necessitats de cada participant, treballant aspectes com l''atenció, la memòria, el raonament, la comprensió i l''expressió oral i escrita. Es realitza en grups reduïts, amb una atenció personalitzada que afavoreix l''aprenentatge i la confiança. ', '1:30 h', 'Grups reduïts i per franges d''edat', 'Descompte. per germans', 'Setembre', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/2Z97Qr-tDEaSxxfLzY408g/zI90-6d2SMaDP9XJrsOy30WiJ9JvHxWgWrB3YK-3OEqXdO9cMxBeXYtjYLL_scH-ZGxp6shucsJdSucR5ZB86B2FN48hDtfhBtsHycPgUBzuhprqretBUAVY1iNcoTI5VUOyRj5NI-Ryu661knVu4w/VLJp-SqUhY3iy6oYT7JI63grXMCTaPj1Zyw5LKtElZ8', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/s5XzTjSoabeIUxO0UCY10Q/ZW1wAjaWGV8ERp596yOB8wHvuSElMnSFYj0cILBe5QzUv7x7Zb0p0uhS69ROLTig8XFLQF7rymut0EVERGHk0OEVG5Ho1ZIHfTKgfgqI3RP-o-05--YBRJqWxiWEEKvHpUfiXOMFB7neO_GyKOdIig/JtggmBwBhAj0StKebkI0QE8vuhwmmhz1lRZ14xLHpqY', '{}', '', 'Taller', '', '', '', '', 'girona')
