VALUES ('recXitaS1iiXZyuzo', 'extraescolar-ioga-teens-12-18-happy-yoga-girona-girona-eixample-girona', 'Ioga Teens', 'Happy yoga Girona', 'recKEk7mmMaH7QZje', 'Girona - Eixample', 'Ioga', '"Ioga"', '12-18', '38', FALSE, TRUE, FALSE, '17:30 a 18:45', 'Dijous', 'Totes les postures de ioga (àssanes) afavoreixen la salut de la columna, la nostra flexibilitat, la nostra circulació i la nostra capacitat de meditació. Hi ha postures que involucren les cames i que estan destinades a desobstruir el sistema circulatori sanguini, postures de ioga que, a través dels braços, afavoreixen el funcionament del cor, postures de ioga que estimulen i equilibren el sistema endocrí i molts exercicis de respiració iòguica (pranaiama) que aporten salut a la psique i claredat a la ment.', '1:15 h', '', '', '', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/9eX29f2cnXvIPH-CZcjJ0Q/MXiKVGQpL9rkHFYr61YkBTDy_R0J6naEvkM3QGmFrKqMh_ooMpMuwO8gMQ5SGJc1kvMCtW69sk2MzAn9Yb_-gI4P694d-AHQFuyasbM8A3Q44_xagSBcu4N5CPCZ_vk80eksEJvAwCRonC-HTp121MNZWZRlOn2fAx-hENx4BR9vnkV_xoM2dNiTYChUT3td/7XwvsKQqG5c8nB4-GwdaUIFe-hb0IEU_2F3UetqkeGM', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/7RsG2WUxcqWq0YFQb-jWsg/FOd2w38u3Is7BLNWDxUDHEtHTnnigpSfK3QbChJRUFvMFaY70dGeZKf_HuTPGh4WP-jL0HZIyNOBBwEp1gakUWw7oaKgYDJ0N3sPWgbHEWUefYJBQfQ03Xl8YNynob5Z58VfD7joU8o5FHoXiGcNVA/R_-fCxfX3xRyGyald54xLKCPQotlbsQ2AhiNJ-7jLOM', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
