VALUES ('recYhJgEr7kh69RSw', 'extraescolar-xines-per-a-nens-de-primaria-6-12-anys-institut-xines-siwei-girona-sant-narcis-girona', 'Xinès per a nens de primària ', 'Institut Xinès Siwei', 'recEK5NjkjVX97lNl', 'Girona - Sant Narcís', 'Idiomes', '"Idiomes"', '6-12 anys', '', FALSE, FALSE, FALSE, 'de 17:15h a 18:45h', '1 dia a la setmana', 'Els nens ja no només aprenen a través de joc, sinó que a poc a poc comencem ja a introduir el reconeixement i escriptura de caràcters. Igual que en les edats anteriors, l''empatia i complicitat amb el professor és fonamental per incentivar l''aprenentatge de l''idioma.', '1:30 h', '', '', '', 'Xinès', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/km3Dmm54PIzbI6SKJ66yEQ/6PDUcavy75g_kKzES4mkuG05QmQ7Ass2qM-758AWhyJMbVmRhwoaVe4K5j1jzHMIlbgRme40UQmz06rUFtGIvWPadH44_zUNuFDklHUnIVTREluu1Z6Ns9KxReKEMAczQk1C7gCoOPhIpKyBqlFAqcWR_5PfjgY1VHNke4Wx_Bw/mEpt6TXX3zqfFLLuDgydDeqyETrEk4bh_s7drp3KQNc', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/hVzqnLgMKMnq8nkZs3JS_Q/OnCB0v9Illn04EsHkpwd8PXhQfLdocQqcsg5iLz3dI02kDGslITo1-2vwASWEZVTXB-EO-DtjFhh8vYv0uTSRkNlEZzuDkWEZSEyVABNK7EvO3XaxeMIqRh37-ZUiIbgit3-fV1op0BWB0A0cnAmXw/7amtOerCg0bixcJIRGHiYvKL5jZwMKzPewsy2qV52eE', '{}', 'Xinès', 'Extraescolar', '', '', '', '', 'girona')
