VALUES ('recZlLtcG5qrZq7CP', 'extraescolar-conectart-troba-el-teu-cami-dins-la-rt-6-18-anys-centre-civic-santa-eugenia-girona-santa-eugenia-girona', 'ConectART: Troba el teu camí dins la''rt', 'Centre Cívic Santa Eugènia', 'recULd44Ln90T6rsz', 'Girona - Santa Eugènia', 'Creativitat i Expressió', '"Creativitat i Expressió"', '6-18 anys', '185 € l''any', FALSE, FALSE, FALSE, '16.30-18.30 h', 'Dilluns', 'Curs enfocat per a totes les edats i els gustos, més experimental, expressiu o clàssic. L''objectiu és trobar el propi camí, un fil a seguir completament personal mitjançant les arts plàstiques, es potencia al màxim la creativitat i l''autonomia.', '2 h', '', '', '', '', 'Greendel15', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
