VALUES ('recZyC89rR5X1ET9H', 'extraescolar-frances-per-adolescents-i-joves-de10-a-18-anys-eica-girona-eixample-girona', 'Francés per adolescents i joves', 'Eica', 'recHgLj4ryjLawaNz', 'Girona - Eixample', 'Idiomes', '"Idiomes"', 'De10 a 18 anys', 'Des de 95', FALSE, FALSE, FALSE, 'De 17:30h a 19:30h', 'De dilluns a divendres (segons nivell)', 'Maximitza els seus dots de comunicació de la forma més efectiva a la nostra escola de Girona. Els nostres cursos d’anglès per nens a partir de 8 anys els brinden una base sòlida de l’idioma per sempre.', '1:30 h', '', '', '', 'Anglès', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/JABOWw4-D0WS_IG_arGiOg/G-ZJTVXkQ9nrUYbkQ_nM5cpnUKOcLi00Nofo2ei1lvHjxzNZclzpLFnfN5Ob2PwaGz7vC8OofbNTmjzgHAgKF_yQ20MVOzKeA5oKh3L81MvUBh1G6JNRedsrI8vU2dOr8xBV8e1-7HPVnjjg0_DZSUVVhZAtFYDLOPGyA9muk9W_LlIc6COWbruspfADy1C_/VRVykDEh2zHwCvRfzPtrZIubLnbrYcY7xD7DIiavNCw', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/aYz-DlRT9dYeZzFb0MiDzA/n13u74ZY_StmDQU288cljiniNGV4BOYBp5IUiF7dH9RKqVzGcwa89EzwCOjG4AE79WCf2EjibD36kqo_dQSx1qPkbVZp1gpcCn6--Wsa2VBtyz3SVjy8tUO2-dG3_g7POwIKAq0BTULIqEpeejGVEQ/qEmBP48aH_h8_-59pYDMNo5lq3U6TAJKOnZh7m03y-I', '{}', 'Francès', 'Extraescolar', '', '', '', '', 'girona')
