VALUES ('recaECdVqVQZuR58l', 'extraescolar-escola-karatedo-sant-daniel-6-9-anys-de-6-a-9-anys-local-social-de-sant-daniel-girona-sant-daniel-girona', 'Escola Karatedo Sant Daniel 6-9 anys', 'Local social de Sant Daniel', 'rec8fCklQ7FxUFQwm', 'Girona - Sant Daniel', 'Salut i benestar', '"Salut i benestar"', 'De 6 a 9 anys', '355€/l''any', FALSE, FALSE, FALSE, 'De 17.30 a 18.30 h', 'Dilluns i dimecres ', 'Eina d''autosuperació i de perfeccionament, de benestar i de salut, té tot el sentit en un món ple d''estrès, contaminació, competència i tendència cada vegada més gran al sedentarisme.', '1 h', '', '', '', '', 'Ass. Catalana de Budo tradicional KYUSHIN RYU ACBTKR', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
