INSERT INTO public.activitats (id, slug, nom, centre, centre_id, barri, categoria, categories, edat, preu, destacada, centre_interessat, destacada_gran, horari, dies, descripcio, durada, alumnes, material, inici, idioma, qui_imparteix, publicada, imatge_url, imatge_thumbnail_url, galeria, subcategoria, tipus, torns, centre_vacances, poblacio_propia, adreca_propia, ciutat)
VALUES ('recaSzKkRnNIqSEd2', 'extraescolar-innovat-2-robotica-educativa-8-11-innova-t-educacio-girona-eixample-girona', 'Innovat 2 - Robotica Educativa', 'Innova''t Educació', 'recPLNJCBuYgE3BwV', 'Girona - Eixample', 'Programació i robòtica', '"Programació i robòtica"', '8-11', '', FALSE, FALSE, FALSE, '17:30-19:00', 'Dimarts i/o Dimecres', 'Robotica educativa per a nens de 8 a 11 anys. Continuitat de Innovat 1 amb robots mes complets de Vex Robotics o Lego. Treball cooperatiu en grups de 3-4 alumnes amb sistema de rols variables. Potenciament de l''emprenedoria i valors de grup. Sessions de robotica alternades amb creacio de videojocs amb softwares com Microsoft Kodu o RPG Maker. Programacio orientada a objectes. Reptes avançats per a participants amb coneixements avançats.', '90min', 'Grups de 3-4', '', 'Setembre', 'Catala', 'Grups de 3-4', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
