VALUES ('recaibPpcbyJ6NIsN', 'extraescolar-dibuix-disseny-i-expressio-6-12-anys-fedac-sant-narcis-girona-sant-narcis-girona', 'Dibuix, disseny i expressió', 'FEDAC Sant Narcís', 'recOAhITlxeUs1sRA', 'Girona - Sant Narcís', 'Creativitat i Expressió', '"Creativitat i Expressió"', '6–12 anys', '31 €/mes · 17 €/mes (1 dia)', FALSE, TRUE, FALSE, '17:00–18:15h', 'Dilluns i Divendres', 'Per als petits artistes que necessiten un espai per expressar-se. A través de diferents tècniques plàstiques, els nens aprenen a mirar el món de forma artística i potencien la seva creativitat i capacitat d''expressió. Una activitat tranquil·la, creativa i molt personal, on cada nen treballa al seu ritme i a la seva manera.', '1:15 h', '', 'Les persones externes a FEDAC Sant Narcís tenen una despesa extraordinària en la quota del primer mes en concepte d''assegurança de 10 €', '', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/4xTLXbYFNrkbzA9rOxKT-A/l74IRUGPpkpbGsNyoyJHQRPKnenSo4ZlElUkOS_Wc4nLkld7AEQalJbRME72jmdbgjX9e0eqd61NarFCPKiS7JKpCrRLz8u0_Z1EwrOK1Sh05OYsA-tmegkST5XMBY3bgfS765MKrZz8oqAzWf1jO94yCL-QhuNwaQ2vPLqmtQc/NsmurfITwOxiE3Dy00CfRFGRa-mLaulEhjsRzal1bGM', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/S4_eJaE5XqBT1qHUKmM10A/RwWTl0qQGXgxDGpeOEQHD3QZRxbNoz0nBdhMiOVGNhxCQXwZ6JqLoaWRXj5U6ckdBSIuEXopXAVCd7I0rQKvXaLX_lqTDU_LRuvO8HnxEIcxoIVScMq7yGgFgkSBABvjbF95LLSi5Od3jKm137ivoA/K9G8qEHxQ9EesNt4xBl4zgQWqMlvVjWFr3zj6QTzRlM', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
