VALUES ('rece5HXsbLybztXxD', 'extraescolar-angles-per-a-joves-10-a-18-anys-up-idiomes-girona-eixample-girona', 'Anglès per a joves', 'UP! IDIOMES', 'reciIofi7Tshw66I8', 'Girona - Eixample', 'Idiomes', '"Idiomes"', '10 a 18 anys', 'Des de 39', FALSE, TRUE, FALSE, '16:30h, 17:00h o 17:30h', 'Dilluns a dijous', 'Per als joves (normalment a partir dels 11-12 anys, coincidint amb l''etapa de l''institut i la preparació per a Batxillerat), UP! IDIOMES fa un gir en la seva metodologia. L''enfocament deixa de ser purament lúdic i es transforma en un mètode dinàmic, orientat a objectius oficials, però molt allunyat de la rigidesa de l''institut.', '1:30 h', 'Grups reduïts', '', '', 'Anglès', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/M3r9DXVUUSuto5-Lu_w76g/a57MMC_SJdpnqS7CiL-l4xU1daKsMtZ8sNd8lkc7-_JEHmyFcnXWWcUBXGL4VF4-JZDE2ElixkzbI5t_PC3CrWKjX59GbKTKk_s_vgGYs63hucN9JHAAZpT4V85Yb2M_AE3-wVKU4eDRQfdCRt4HRM3UPqBI9uodA8XKBJAtFUaVEoClVTZ7jggyfNh3ZYsn2RdDedGnBGIoLmkQuKXMJQ/jgre0p3LNJNPBxcRmd-i1oqTI_ntbKNilOwEllo8jsw', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/Xt-5p7tSB_SbnE3zSzn5sw/chX0-D6dhdxJX5sy1kP5GRzSmSOqCyDUaT3dqlGYTszXz8JmdN_gvmUOY4ix_d3g99XNJM9TIfrTUeD3hP2peKtgylNPNVJVWO7Vw0MHtgfuuv4KnCbNJJs2boIrnjITBBhU9R-Zv-0VeHU5t39J9w/LG_opQgPvCnyRCed_3KfpoUB1tGSMP1TTVh0Z5JVe8s', '{}', 'Anglès', 'Extraescolar', '', '', '', '', 'girona')
