VALUES ('recerqKWBBqtoRTLW', 'extraescolar-escola-de-natacio-nemos-de-6-mesos-a-2-anys-fundacio-torremirona-esport-i-salut-navata-girona', 'Escola de Natació Nemos', 'Fundació Torremirona - Esport i Salut', 'recT618bKVEBAVmpP', 'Navata', 'Esports', '"Esports"', 'De 6 mesos a 2 anys', '44 € socis / 70 € no socis', FALSE, TRUE, FALSE, '30 min', 'Un dia a la setmana', 'La Fundació TorreMirona - Esport i Salut té com a objectiu principal la promoció i la pràctica de l''esport com a mitjà per a la millora de la qualitat de vida de les persones. Treballem per fomentar el desenvolupament personal i social a través de l''esforç, el respecte, el compromís i la solidaritat, contribuint així a crear una societat més sana, activa i solidària.', '', '', '', '', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/swq9uwYjnjInIvBdZZTJRw/qDL2P4PM9XqaGzOToOpML55K-5ULXZxnaI7nydvHtb8lFhQudHnpZ4regxFccw2nskMKMOFaihnlzkcOp9cAHYxJ4AU6mNFAzR-rLGY9SGgKkbTE2A-475LV3nmBuyVcntR7L3SB1Lid1nH6fp12Q156qm9bcQFKM9M3qdAq0wZq8QkGMA3V5rKKlL2dcsyZ/v4pZEUpbjzRZEgRRPBrrtW8v65atUr0Q6y8CBiDNvX4', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/e9zjFm3kmLdb7iHL1ZPppw/tyKtxgaRSxFIsttQKK_Ztu54W7f5GUY2HiEOgnGG7hzIxwiw5-dRXaZHwfX4xFmUqEB2kRVdcf98rRfQL0Iq7Lt2pawLIJCUavSppitm5UBgqLMW5NuPleHpakKdm9cw17Plwx3iF2X97gbqTtw4ww/l7YG5s2K1rFCx7b1ETIOm--hY3Q2ZfUNhMRAmZhKQD8', '{}', 'Natació', 'Extraescolar', '', '', '', '', 'girona')
