VALUES ('recfr9Oyi8WjmgAYS', 'extraescolar-judo-prebenjami-i-benjami-6-12-anys-geieg-sant-narcis-girona-sant-narcis-girona', 'Judo Prebenjamí i benjamí', 'GEiEG - Sant Narcís', 'recifhRNk0AJriirG', 'Girona - Sant Narcís', 'Esports', '"Esports"', '6-12 anys', 'Des de 33', FALSE, FALSE, FALSE, '18:00 a 19:00 h', 'Dilluns, dimarts, dimecres i divendres', 'El judo al GEiEG és més que un esport, és una forma de vida. Aprèn, competeix i creix personalment en una secció pensada per a totes les edats.', '', '', 'Per fer aquesta activitat cal ser soci del GEiEG (és un quota addicional al preu de l’activitat)', '', '', '', TRUE, '', '', '{}', 'Defensa personal', 'Extraescolar', '', '', '', '', 'girona')
