VALUES ('recfsh8IcLH2cb0PC', 'extraescolar-pre-ballet-en-angles-3-anys-programa-melody-bear-de-londres-copy-de-3-a-5-anys-the-classical-ballet-school-girona-eixample-girona', 'Pre ballet en anglès 3 anys (programa Melody Bear de Londres) copy', 'The Classical Ballet School', 'reclfLaYHcc552ANs', 'Girona - Eixample', 'Dansa', '"Dansa"', 'De 3 a 5 anys', '25/trimestre', FALSE, TRUE, FALSE, 'De 17:30 a 18:30h', 'De dilluns a dijous', 'Desenvoluparem el sentit del ritme i la coordinació a través de la imaginació. La Melody, la nostra mascota anglesa, ve de molt lluny i només parla anglès. Li encanta ballar i segur que t’agradarà descobrir el món del ballet amb ella!', '1 h', '', 'Un acompanyant per infant.', '', 'Anglès', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/k-3iaXs59QvDZhpHg_nI3g/R9TLYFxGDUknJ3mAznFWdas9u6uXSyFD06HuBX-Sy8dONNGw_SZPt3GmtUqMa9q9GR7cPsB9l7aHu3WhrBl0uOnfmuQhhz3IMBbXDEaBZPaVTK2Hnb8tanTNDTrjWeH4SsBwp39z8v94Q28uYnGpYWVMNg_kJnfuO-jpsulQNIg/97atkd98eEPtDzYq85KUv795bBX8bZ8vckLd7dDaQVE', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/VwPdmlErTS7eXr9ZbO6TOg/PsKvyl6eEiRya-Oq9HtjTtwLJszs2JtfH75KAd18-Y81jmGdktB5-OkLBlAcVpvfjlhi3mFgYzpDgp73nxP6HfjZ_4xKQ-2XOCPITWnGRN9fQ3Arq2q7ETet9FtUtlp73ltSGM5Lr624DHDTA0CGCA/Fg4zViFNqfkTDVkuyWMJleYmpc_z3XTPm3gaXas2ZK8', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
