VALUES ('rech1lXA5wcRTKOCV', 'extraescolar-castella-per-a-nens-8-11-up-idiomes-girona-eixample-girona', 'Castellà per a nens ', 'UP! IDIOMES', 'reciIofi7Tshw66I8', 'Girona - Eixample', 'Idiomes', '"Idiomes"', '8 - 11', 'Des de 15€/hora', FALSE, TRUE, FALSE, '16:00 - 17:00', 'Dilluns a dijous', 'Fem servir un mètode actiu, lúdic i basat en la immersió natural, pensat específicament per a una edat on la prioritat és que l''idioma entri a través de l''oïda i el joc', '1 h', 'Grups reduïts', '', '6 de juliol', 'Castellà', 'Professors natius', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/aswYdIzUnr5F11P_vRRQKQ/70RiM8aKAe72OZQakw4ZDTjR5Li8uHRkc54rDGFUVJ7XtKpyPbnRlhB4X2UZozGAYfuS3Glq5mAoecudvwYSwAq4Mqzyst34MAu_8xoRYLczbOg8dYt7B6DIvtIELSUo1SpjE3uC2gS65XDNcUceBw/6jNIrhVNakM1wR8Wsky3UbwPdSrDGlA_4oPTMU37thk', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/3Bd815_r4niw_prkvtVowA/zeQy6alyZnbKuSMqjt234sbqWveqMw5_0XDT202tyqRn4BqZwiLb8B3MA2zHqWo9AxRaZ74GrunFdRtxOZeBbbcbrMiyS5sIgRxSopkOnCrkDQYNe1cvAHxTwyOyKxYmwN4ZuUICmBWFNvqj1kcNrg/HSbFgXtN6nuh2D2axJ6eQQ0vkLzf_2rf3R_atfgfOC0', '{}', 'Castellà', 'Extraescolar', '', '', '', '', 'girona')
