VALUES ('rechxmVhuunIBFuA0', 'extraescolar-gimnastica-artistica-infantil-13-14-anys-geieg-sant-narcis-girona-sant-narcis-girona', 'Gimnàstica Artística Infantil', 'GEiEG - Sant Narcís', 'recifhRNk0AJriirG', 'Girona - Sant Narcís', 'Esports', '"Esports"', '13-14 anys', '41,00', FALSE, FALSE, FALSE, '18:30 a 20:30 h', 'Dimarts i dijous', 'Descobreix la màgia de la gimnàstica artística al GEiEG. Treballem perquè cada gimnasta desplegui el seu potencial en un ambient segur i motivador.', '2h', '', 'Per fer aquesta activitat cal ser soci del GEiEG (és un quota addicional al preu de l’activitat)', '', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/c4Z2rfa5ZpaELqOQDqPwtA/SGH1Bk8IiHBRklb0NdXg4oksBUcsCo766JLlptIf1hYTuq98Zc1_FsxZI98W22EhuwrxS_91zkkDFpF9t6thgYpP2MzzPOoBqRC8cJW5EwtJRE8bJpkGA8YQcvqBYMM8QbagrvKPLVkKFmWliWbCeGuiZwiWQeVXP80yKTF7gHceuGwHizJOB0CsG-3w3wGM/oH-0-yorPcrtlytB2bjRcTYWnMHa8D4O-Bim0g7GGNs', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/lgXwtzyNRYQG4Ihq4mpIQA/0-8LHMtkCdvRFFdj-2oyrcoNCC-MyGE8iIrGUY87VL4poc4VaaAK6gNdi0NXxWR01Iy8z3jJLlw7r2dvwH1fQ7CLgfvFb561JFfmz4sSyjyk5JFTena3B0ORKGHTnCXV-XK673DlNNsmrIzgcdvMQQ/erCiteoSFvFaFiyUL858P_LooQF0KkVYw4ykDicTlpo', '{}', 'Gimnàstica', 'Extraescolar', '', '', '', '', 'girona')
