VALUES ('recj7M8wruH52tTMm', 'extraescolar-pre-dansa-3-1r-primaria-6-7-anys-girona', 'Pre-Dansa 3', '', NULL, '', 'Dansa', '"Dansa"', '1r primària (6–7 anys)', '', FALSE, FALSE, FALSE, '17:30–18:30', 'Dimecres', 'Pre-Dansa 3 és el nivell de transició entre l''etapa infantil i el ballet clàssic, adreçat a nens i nenes de 1r de primària (6–7 anys). A l''Escola Girona en Dansa, les classes es fan els dimecres a la tarda i combinen tècnica bàsica i creativitat.', '1 hora', '', '', '', '', '', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
