VALUES ('recnHtuMmOfFnOqKR', 'extraescolar-innovat-1-introduccio-a-la-robotica-6-7-innova-t-educacio-girona-eixample-girona', 'Innovat 1 - Introduccio a la Robotica', 'Innova''t Educació', 'recPLNJCBuYgE3BwV', 'Girona - Eixample', 'Programació i robòtica', '"Programació i robòtica"', '6-7', '0', FALSE, FALSE, FALSE, '17:30-19:00', 'Dimarts i/o Dimecres', 'Introduccio a la robotica per a Cicle Inicial. Els nens construiran i programaran els seus primers robots amb plataformes educatives com Vex Go Lego o Micro:bit. Aprenentatge experimental incentivant la curiositat. Sessions alternades amb creacio de videojocs i animacions. Disseny programacio i pensament computacional en 3D.', '90min', 'Grups reduits', '', 'Setembre', 'Catala', 'Grups reduits', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
