VALUES ('recnKS1PK27HZSZ2E', 'extraescolar-llenguatge-4-9-anys-escola-de-musica-sant-gregori-sant-gregori-girona', 'Llenguatge 4', 'Escola de Música Sant Gregori', 'rec8bSYPwdb4jZCLe', 'Sant Gregori', 'Música', '"Música"', '9 anys', '80', FALSE, TRUE, FALSE, '18:10 a 20:10 h', 'Dijous', 'Pedagogia activa basada en la participació activa, l''expressió vocal, el moviment corporal i la improvisació, amb l''objectiu de desenvolupar l''oïda, la veu, el sentit rítmic... fent que tots els alumnes gaudeixin i creixin gràcies a la música', '2 h', '', '', '', '', 'Adrià i M. Àngels', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/thBjQI7v6mqVSUI0dnO-Vw/-FgxrHofObjd-9HWLzSfliDGBDk8L3RkxlGNLAyJ4lqkbqXQgUmZdwXs9dKsNfdiXYenVfsDO5FRfPN0MACnqnZGQwzM7E351lQ9svY6Y9G39JT__UmFvNarz20zbJTc9kn_KsAQPNxwO4qESFsLtAV2weUnErocS0gMOWPiU4A/AD-Ev7nprw8OuifL0pHaXC05fPnUosMNjsi7WUMwFFo', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/PdGa2w2cvdbvEvAG3gopQg/TqFzQenLs0xCjfyfTI3Oqmmy5VwCRdjuj3ST5umWPJdm2Za-0nQVqVDIhRMZKUJtizEuufcZfsgvVqkEeMN_K5C3TRorJ4ab7cpOgYeH5J6wBxnVNEFIOdj1FhRPObjL-4GsAjHZf45-cV7nKFP33w/1So-OWPlGyQuX-6E-Oq0FmHqFqCTyrFiUnfbKggTk_g', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
