VALUES ('recorbb0z4L69mzSR', 'extraescolar-ciclisme-muntanya-tecnificacio-7-18-anys-escola-ciclisme-girona-girona-riders-girona-domeny-i-fontajau-girona', 'Ciclisme Muntanya Tecnificació', 'Escola ciclisme Girona - Girona Riders', 'recXcvKvWb2CrQyb6', 'Girona - Domeny i Fontajau', 'Esports', '"Esports"', '7-18 anys', 'Des de 36', FALSE, TRUE, FALSE, '17:30 a 19:00 h', 'Dimarts i dijous', 'Des de Girona Riders oferim un extraescolar de ciclisme de muntanya, on es desenvolupa la tècnica específica d’aquest esport. Els infants aprendran a conduir amb seguretat i control la bicicleta.', '90min', 'Fem els grups segons el nivell tècnic i físic de cada participant.', '', '', 'Catala', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/7-Cd98NjczNmspKwvKMWIQ/icfg85PU9WAlbQLabVDAU9oeGA9iyDq4HmkJmPU64O0483o-yGITWMnrJIB58yzQbwhhKg0KFxcrkNzkfiDF6A7PsqxDWri_6-GSe9dxbwWl5QJal4dLDwVyRdt_j-y37Xykdhe7UW2daQOaEylSUJad469FuSyTb0kiQDyE5z3Ou8pA4XJLkfxRQ9xTI6cE/dp-T2Z8qMquQJjQRnOvuez51DJg0mzeu7CXRpnUcbTA', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/IyVYK4fK7Bva3ah3XAvqig/cwpTCUfCY8L10yubcSG4qC7L_1qJVjjRKqxfmUJR0IbI1p0NGwRYGKprPizBQQ24sNaNn2oVJMkfyc_Z8Ho_ttaEFKSnCfbGDLOh-Ph8_zdqx-ur-WFNyFDx6P1lDrCjfKOUs3gy4ME1i-BpFejTHg/uv2fn97YOTk9DBHuOxeIqxY0Uavkp0_sOr8fWd3Viy4', '{}', 'Ciclisme', 'Extraescolar', '', '', '', '', 'girona')
