VALUES ('recrPRWYF63LWZpKf', 'taller-art-i-suc-a-partir-de-8-anys-imagina-art-girona-eixample-girona', 'Art i Suc', 'Imagina Art', 'recFEBmWiPvpcOMR5', 'Girona - Eixample', 'Creativitat i Expressió', '"Creativitat i Expressió"', 'A partir de 8 anys', '', FALSE, TRUE, FALSE, '', '', 'Una sessió creativa amb un toc refrescant. Els nens experimenten amb tècniques artístiques mentre gaudeixen d''un suc. Perfecte per a aniversaris, sortides en grup o una tarda diferent en família.', '1:30 h', '', '', '', '', '', TRUE, '', '', '{}', '', 'Taller', '', '', '', '', 'girona')
