VALUES ('recy0PFpJTlI5UsAH', 'extraescolar-atletisme-sub-16-tecnificacio-15-16-anys-geieg-palau-sacosta-girona-montilivi-palau-girona', 'Atletisme Sub-16 (tecnificació)', 'GEiEG - Palau Sacosta', 'recgetecLsdwmaX6k', 'Girona - Montilivi-Palau', 'Esports', '"Esports"', '15-16 anys', '53', FALSE, FALSE, FALSE, '17:45 a 19:15 h', 'Dilluns, dimecres i divendres', 'Descobreix l’atletisme com mai ho has fet! Uneix-te a una secció que combina gairebé 100 anys d’història amb la il·lusió i l’energia del futur. Amb el GEiEG, l’esport es transforma en una experiència emocionant per a totes les edats i nivells.', '', '', 'Per fer aquesta activitat cal ser soci del GEiEG (és un quota addicional al preu de l’activitat)', '', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/aVe_4AYmApndsMEpYadPZQ/DynvmdOGTqfwS0xl2lTu_Y3XFQL2kXSdU8dV2hJQ85zhX13Iwlb3XzJ1kvwBNn_-c6dvg-7mP8_JSTaoqNjBtUx37nDKLt0vn1dPdL51df6vPjJnUTRnG_NYOFQhleqSCaye5cBpRA6_O3YTy4oYa2yst9D4dXyv19LOC15zjf-mjM5qM0LUDCy1mZwO6GSH/xxZ9ZNP6uKfPedzIkZMKxm6UTqAjSbtGvdeWYLIQgGM', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/8FLOKuT8phrJphiNk1B5-Q/wxZAtsJA9awsaRyGTdfckZzTFn-jSLm4CUo3znvIsv1X-rZUAj8KukR31cPJvI7aT4A3iL_6egf6MIyEqdu2OhpkAFfcFtkPqIYCFW0QLdJA8XuKS1vtjMOPNC3FUF7_YCQ5z9cW33ihDkFRpUs3Ug/OsSTs2AScR0PBN80u1IxfXnZ0dCZjDv8dwSEagvQUqg', '{}', 'Atletisme', 'Extraescolar', '', '', '', '', 'girona')
